"""The ten printed exercise parts closing chapter XII, pp. 292–293 (Atanasyan 2023)."""
import argparse
import json
from math import cos, hypot, radians, sin, sqrt
from coordinate_curves import graph
from triangle_sine_area import area
from trigonometric_signs import grade
from vector_scaling import BOOK, ROOT

OUT=ROOT/'geometry-course/textbook/data/chapter-twelve-finale.json'


def drawing(title,points,edges,circle=None):
    return graph(title,points,edges=[tuple(pair) for pair in edges.split()],circle=circle,radius_line=False)


def exercise(n,part,task,reason,hint,steps,views,checks,refs,caption):
    page=292 if n<=1161 else 293
    e=area(n,part,[page],task,reason,hint,steps,views,checks,refs=refs)
    e['help'][1]['text']=hint
    e['visualization']['caption']=caption
    e['visualization']['model']['description']=caption
    e['review']['reviewer']=f'Сверены точная формулировка и обозначения с печатной с. {page} в издании 2023 года. Для каждой модели измерены исходные и новые конфигурации.'
    return e


def trapezium():
    def scene(label,t,scale=1):
        h=t*sqrt(3)/2
        p={'D':(0,0),'A':(16,0),'C':(t/2,h),'B':(t/2+8,h),'K':(12,0),'H':(t/2,0)}
        return drawing(label,{k:(scale*x,scale*y) for k,(x,y) in p.items()},'AB BC CD DA CK CH')
    views=[scene('Если данная сторона AB',12),scene('Если данная сторона CD',4*sqrt(7)),scene('Первая трапеция в половинном масштабе',12,.5)]
    hint='Запись «боковая сторона» на с. 292 оставляет выбор между AB и CD. Положи CD=t, опусти CH на AD. Сравни площади трапеции и треугольника DCK прежде, чем находить t.'
    e=exercise(1159,None,'У трапеции ABCD основания AD=16 см и BC=8 см, ∠ADC=60°. На с. 292 одна боковая сторона названа равной 4√7 см без обозначения вершинами. Через C проведена прямая, делящая площадь пополам. Найди площадь и длину части этой прямой внутри трапеции для обоих прочтений условия.',
        'Пусть h=t√3/2, где CD=t. Полная площадь S=12h. Точка K на AD с DK=12 даёт S(DCK)=12h/2=S/2, значит искомый отрезок CK. Если AB=4√7, то AB²=(8−t/2)²+3t²/4=t²−8t+64=112, откуда t=12. Получаются S=72√3 см² и CK=12 см. Если CD=4√7, то h=2√21, S=24√21 см² и CK=√(256−48√7) см. Первый набор совпадает по числам с ответом на с. 400.',hint,[
        ('Найди конец делящего отрезка','Сравни половину площади трапеции 6h с площадью DCK, равной DK·h/2. Получается DK=12. Эта точка лежит на AD; при движении K от D к A площадь треугольника строго возрастает.','Половина площади и половина основания — разные величины, поэтому DK не равен 8.'),
        ('Разбери оба выбора стороны','Положи D=(0;0), A=(16;0), C=(t/2;h), B=(8+t/2;h). Для AB=4√7 реши t²−8t−48=0 и отбрось t=−4. Для CD=4√7 подставь t непосредственно. В каждом случае CK²=(12−t/2)²+3t²/4=t²−12t+144.','Проверь, какая сторона имеет заданную длину на выбранном рисунке.'),
        ('Уменьши первую фигуру вдвое','Теперь AD=8, BC=4, CD=6 и DK=6. По подобию CK=6 см, площадь в четыре раза меньше прежней, то есть 18√3 см².','Отрезок масштабируется линейно, а площадь квадратично.')],views,[
        ('Чему равно DK в каждой из двух исходных трапеций, в см?','12','Реши DK·h/2=6h.'),('Каков коэффициент при √3 в новой площади после уменьшения первой трапеции вдвое?','18','Раздели 72 на четыре.')],[104,106],'На обоих исходных чертежах один и тот же отрезок DK и высота CH. Сопоставь AB и CD с указанной длиной. Третий чертёж задаёт новые размеры.')
    e['answer']['prompt']='Запиши обе пары «площадь, отрезок», укажи для каждой известную сторону и объясни равенство площадей.'
    return e


def circumradius():
    def scene(title,c,b,alpha):
        a=radians(alpha);Fx=b*cos(a);Fy=b*sin(a)
        center=(c/2,(b*b-c*Fx)/(2*Fy));R=hypot(*center)
        return drawing(title,{'A':(0,0),'B':(c,0),'C':(Fx,Fy),'T':center},'AB BC CA TA TB TC',('T',R))
    views=[scene('Острый исходный угол A',4*sqrt(3),3,30),scene('Тупой угол с тем же синусом',4*sqrt(3),3,150),scene('Новые перпендикулярные стороны 6 и 8',6,8,90)]
    hint='Вычисли sin A=2S/(AB·AC). Уточнение об остром угле однозначно выбирает A. Радиус равен BC/(2 sin A); сторону BC сначала найди по теореме косинусов.'
    e=exercise(1160,None,'Площадь ABC равна 3√3, острый угол A заключён между AB=4√3 и AC=3. Найди радиус окружности, проходящей через все три вершины.',
        'sin A=6√3/(4√3·3)=1/2. Из условия A=30°, значит cos A=√3/2. Тогда BC²=48+9−2·4√3·3·√3/2=21. По расширенной теореме синусов R=BC/(2 sin A)=√21.',hint,[
        ('Восстанови угол по площади','Подставь в удвоенную площадь две стороны и их включённый угол. Синус 1/2 подходит также для 150°, но этот угол не острый.','Для косинуса необходимо выбрать правильную ветвь угла.'),
        ('Найди сторону напротив A','При верном угле BC²=21. Для сравнения второй чертёж намеренно показывает 150°: такая же площадь, но BC²=93. На нём центр окружности расположен иначе.','Не используй 93 для исходного острого угла.'),
        ('Проверь на прямоугольном треугольнике','При катетах AB=6 и AC=8 получаем BC=10, а центр окружности лежит в середине гипотенузы. Поэтому R=5.','В формуле радиуса стоит удвоенный синус угла напротив выбранной стороны.')],views,[
        ('Сколько равно BC² для исходного острого угла?','21','Вычти 36 из 57.'),('Чему равен R на новом чертеже с катетами 6 и 8?','5','Возьми половину гипотенузы 10.')],[104,105,106],'T — центр окружности, проходящей через A, B, C; три радиуса равны. Второй чертёж специально показывает исключённый тупой угол.')
    return grade(e,['√21','sqrt(21)','√(21)'],hint,'Введи точный радиус окружности.')


def rhombus_area():
    def scene(title,alpha,a):
        theta=radians(4*alpha);s=a*sin(radians(3*alpha))/sin(radians(alpha))
        n=(s*cos(theta),s*sin(theta))
        return drawing(title,{'M':(0,0),'Q':(s,0),'N':n,'P':(s+n[0],n[1]),'F':(s+a*cos(theta),a*sin(theta))},'MN NP PQ QM MP MF')
    views=[scene('Угол ромба 60°, FQ=1',15,1),scene('Квадрат как частный случай, FQ=1',22.5,1),scene('Новый ромб с углом 120°, FQ=1',30,1)]
    hint='Диагональ MP делит угол ромба пополам, а MF делит уже угол PMQ. В треугольнике MQF углы при M и F равны α и 3α. Найди MQ по синусам, затем возьми площадь ромба.'
    e=exercise(1161,None,'Дан ромб MNPQ, MF — биссектриса треугольника MPQ, ∠NMQ=4α, FQ=a. Вырази площадь ромба через a и α.',
        'Имеем ∠QMF=α, ∠MQF=180°−4α и ∠MFQ=3α. По теореме синусов MQ=a sin(3α)/sin α. Поэтому S=MQ² sin(4α)=a² sin²(3α) sin(4α)/sin²α. У выпуклого невырожденного ромба 0°<α<45°.',hint,[
        ('Разбери две биссектрисы','Диагональ MP делит угол 4α на два по 2α. Вторая биссектриса MF делит угол между MQ и MP, поэтому ∠QMF=α. Угол в Q соседний с углом в M; значит в треугольнике MQF остаётся 3α при F.','MF относится к треугольнику MPQ, а не ко всему углу NMQ.'),
        ('Свяжи сторону с FQ','Напротив α лежит FQ=a, напротив 3α — MQ. Их отношение равно отношению синусов. Площадь есть квадрат полученной стороны, умноженный на sin 4α. При α=22,5° ромб становится квадратом.','Возводи в квадрат всё выражение для стороны, включая знаменатель.'),
        ('Проверь на ромбе с углом 120°','Пусть a=1 и α=30°. Тогда MQ=sin 90°/sin 30°=2. Получаем S=4 sin 120°=2√3.','Широкий угол ромба допустим; его синус положительный.')],views,[
        ('Сколько градусов в угле MFQ на первом чертеже при α=15°?','45','Умножь α на 3.'),('Какова новая сторона MQ при α=30° и a=1?','2','Раздели 1 на 1/2.')],[104,105],'Отрезки MP и MF последовательно делят угол при M. Точка F остаётся на PQ; сравни угол MFQ в трёх ромбах.')
    return grade(e,['a²sin²(3α)sin(4α)/sin²α','a^2*sin(3*alpha)^2*sin(4*alpha)/sin(alpha)^2','(a*sin(3*alpha)/sin(alpha))^2*sin(4*alpha)'],hint,'Введи формулу площади. Для угла можно писать alpha; квадрат обозначай ^2.')


def weighted_point():
    def scene(title,k):
        B=(4,0);C=(1,3);M=tuple((u+k*v)/(1+k) for u,v in zip(B,C))
        return drawing(title,{'A':(0,0),'B':B,'C':C,'M':M},'AB BC CA AM')
    views=[scene('BM вдвое длиннее MC',2),scene('Предельный случай k=0, M совпадает с B',0),scene('Новое отношение k=1: середина стороны',1)]
    hint='Если BM=k·MC, то BM составляет k/(1+k) от BC. Вырази вектор AM через стрелки из A и только затем возведи в скалярный квадрат.'
    e=exercise(1162,None,'Точка M лежит на BC треугольника ABC, BM=k·MC, b=AC, c=AB. Докажи (1+k)²AM²=k²b²+2bck cos A+c².',
        'Вектор BM равен k/(1+k) от BC. Поэтому AM=AB+k(AC−AB)/(1+k), то есть (1+k)AM=AB+kAC как равенство векторов. Скалярный квадрат правой части равен c²+2kbc cos A+k²b², что и требовалось.',hint,[
        ('Найди координаты точки деления','Если B=(4;0), C=(1;3), k=2, то от B нужно пройти две трети отрезка BC. Получаем M=(2;2), откуда AM²=8.','Доля пройденной стороны равна двум третям, а не одной трети.'),
        ('Раскрой квадрат с весами','Коэффициент k относится к AC: при k=0 исходная точка M совпадает с B. Смешанное слагаемое в квадрате равно 2k AB·AC=2kbc cos A.','Возведение суммы в квадрат порождает два одинаковых смешанных слагаемых.'),
        ('Проверь середину','Пусть k=1. Тогда M=(2,5;1,5), AM²=8,5. Обе части формулы равны 34, так как |AB|²=16, |AC|²=10 и AB·AC=4.','У середины коэффициенты двух конечных точек равны.')],views,[
        ('Какому числу равно AM² при k=2 на первом чертеже?','8','У M координаты (2;2).'),('Чему равно 4AM² для новой середины?','34','Вычисли 4·(2,5²+1,5²).')],[95,110,112],'M делит BC в отношении BM:MC=k:1. В граничном случае две метки сливаются в одну.')
    e['answer']['prompt']='Докажи равенство, приведя сначала формулу для вектора AM, затем её скалярный квадрат.'
    return e


def coordinate_trapezium():
    def scene(title,scale,dx):
        p={'A':(-1,2),'B':(1,-2),'C':(2,0),'D':(1+dx,6)}
        return drawing(title,{n:(scale*x,scale*y) for n,(x,y) in p.items()},'AB BC CD DA AC')
    views=[scene('Исходные координаты',1,0),scene('Все координаты удвоены',2,0),scene('Сдвинь только D в (3;6)',1,2)]
    hint='Направления AD=(2;4)=2BC. Сравни отдельно AB и DC, затем найди площадь как сумму треугольников ABC и ACD с помощью определителей.'
    e=exercise(1163,None,'Координаты по порядку: A=(−1;2), B=(1;−2), C=(2;0), D=(1;6). Докажи, что ABCD — трапеция, и найди площадь.',
        'AD=(2;4), BC=(1;2) параллельны. AB=(2;−4) и DC=(1;−6) неколлинеарны: определитель 2·(−6)−(−4)·1=−8. Диагональ AC разбивает выпуклую трапецию на треугольники с удвоенными площадями |det(AB,AC)|=8 и |det(AC,AD)|=16. Искомая площадь (8+16)/2=12.',hint,[
        ('Проверь противоположные стороны','Две координаты AD вдвое больше соответствующих координат BC. Для другой пары постоянного множителя нет. Значит пара параллельных сторон ровно одна.','Меняя порядок концов вектора, поменяй оба знака.'),
        ('Сложи две площади','AC=(3;−2). Из него и AB получаем определитель 8, а из AC и AD — 16. При общем увеличении координат вдвое обе площади увеличатся в четыре раза, полная станет 48.','Определитель даёт удвоенную площадь треугольника.'),
        ('Измени только вершину D','На новом рисунке D=(3;6), поэтому AD=(4;4) больше не параллельно BC. Вторая удвоенная площадь теперь 20, первая осталась 8, так что площадь четырёхугольника 14.','Метод разбиения диагональю действует и после утраты параллельности.')],views,[
        ('Чему равна площадь при удвоении всех координат?','48','Умножь исходную площадь 12 на 2².'),('Какова новая площадь после сдвига D в (3;6)?','14','Половина суммы 8 и 20.')],[111,112],'Диагональ AC задаёт два слагаемых площади. Исходные и изменённые точки подписаны в условии и у переключателей.')
    return grade(e,['12','12,0','12.0','12 кв. ед.'],hint,'После обоснования параллельности введи площадь четырёхугольника.')


def cevians():
    def scene(title,b,c,alpha):
        t=radians(alpha);B=(c,0);C=(b*cos(t),b*sin(t))
        # BD/DC=c/b; the weight of C in D is c/(b+c).
        D=tuple((b*x+c*y)/(b+c) for x,y in zip(B,C));M=tuple((x+y)/2 for x,y in zip(B,C))
        if b==c:M=D
        return drawing(title,{'A':(0,0),'B':B,'C':C,'D':D,'M':M},'AB BC CA AD AM')
    views=[scene('b=6, c=3, A=120°',6,3,120),scene('Равные стороны 6, угол 120°',6,6,120),scene('Прямой угол между сторонами по 4',4,4,90)]
    base='В ABC обозначены b=AC, c=AB. Отрезок AD — биссектриса, AM — медиана.'
    hint_a='Сложи площади ABD и ACD по общему углу A/2. Сравни с площадью ABC, затем замени cos(A/2) через cos A, выбрав положительный корень.'
    a=exercise(1164,'а',base+' Докажи AD=(2bc/(b+c))·√((1+cos A)/2).',
        'Равенство площадей даёт bc sin A=(b+c)AD sin(A/2). Так как sin A=2 sin(A/2) cos(A/2), получаем AD=2bc cos(A/2)/(b+c). Половина внутреннего угла остра, поэтому cos(A/2)=√((1+cos A)/2).',hint_a,[
        ('Раздели площадь биссектрисой','Слева удвоенная площадь bc sin A. Справа сумма c·AD sin(A/2) и b·AD sin(A/2), так как обе части образуют одинаковый половинный угол.','AM не обязан делить угол пополам: на первом чертеже M и D различны.'),
        ('Выбери знак корня','Для невырожденного треугольника 0°<A/2<90°. Поэтому из cos²(A/2)=(1+cos A)/2 следует положительный корень. В равнобедренной модели при b=c=6 и A=120° получаем AD=3.','Равенство квадратов без знания знака не определяет косинус однозначно.'),
        ('Проверь прямоугольный случай','При b=c=4 и A=90° формула даёт AD=4/√2=2√2, квадрат длины 8.','Биссектриса прямого угла равнобедренного треугольника одновременно медиана и высота.')],views,[
        ('Какова AD при b=c=6 и A=120°?','3','Умножь 6 на cos 60°.'),('Чему равен новый квадрат AD при равных сторонах по 4 и прямом угле?','8','Возведи 2√2 в квадрат.')],[101,104],'В неравнобедренном треугольнике D и M различны. При равных боковых сторонах точки совпадают и получают общую метку.')
    hint_b='Медиана направлена в середину BC, поэтому 2AM=AB+AC как равенство векторов. Раскрой скалярный квадрат и извлеки неотрицательный корень.'
    b=exercise(1164,'б',base+' Докажи AM=½√(b²+c²+2bc cos A).',
        'Середина M даёт AM=(AB+AC)/2 в векторной записи. Следовательно 4AM²=|AB|²+|AC|²+2AB·AC=c²+b²+2bc cos A. Поскольку длина положительна, деление корня на два даёт требуемое выражение.',hint_b,[
        ('Сложи векторы из A','На первом чертеже AB=(3;0), AC=(−3;3√3). Полусумма равна (0;3√3/2), откуда AM²=27/4.','У медианы берётся среднее двух векторов, у биссектрисы обычно другие веса.'),
        ('Объясни знак смешанного члена','Слагаемые складываются, поэтому стоит +2bc cos A. При тупом A само значение косинуса отрицательно. На втором чертеже обе стороны 6 и обе проведённые линии совпадают.','Знак плюс перед косинусом сохраняется и при тупом угле.'),
        ('Проверь на прямом угле','Если b=c=4 и cos A=0, получаем 4AM²=16+16=32. Тогда AM²=8; та же длина вышла для биссектрисы только благодаря равенству сторон.','В общем треугольнике доказанные формулы для AD и AM различаются.')],views,[
        ('Каково 4AM² на первом рисунке с b=6,c=3,A=120°?','27','Вычисли 36+9−18.'),('Каково 4AM² при новых b=c=4, A=90°?','32','Сложи два квадрата 16.')],[95,110,112],'AM проведена в середину BC, AD делит угол A. В двух последних симметричных примерах M совпадает с D.')
    return [a,b]


def rhombus_test():
    def scene(title,B,D):
        C=tuple(x+y for x,y in zip(B,D))
        return drawing(title,{'A':(0,0),'B':B,'D':D,'C':C,'T':tuple(x/2 for x in C)},'AB BC CD DA AC BD')
    views=[scene('Ромб со сторонами по 5',(5,0),(3,4)),scene('Квадрат со сторонами по 3',(3,0),(0,3)),scene('Прямоугольник 4 на 2',(4,0),(0,2))]
    hint='Пусть AB=u, AD=v. Диагонали направлены как u+v и u−v. Раскрой их произведение: смешанные члены взаимно уничтожатся.'
    e=exercise(1165,None,'Диагонали параллелограмма взаимно перпендикулярны. Докажи, что все его стороны равны.',
        'Выбери AC=u+v и DB=u−v. Тогда 0=AC·DB=|u|²−|v|², откуда соседние стороны равны. Противоположные стороны равны у любого параллелограмма, поэтому все четыре стороны равны.',hint,[
        ('Различи стороны и диагонали','В первой модели u=(5;0), v=(3;4). Значит AC=(8;4), DB=(2;−4). Их произведение 16−16=0, хотя стороны имеют разные направления.','Равенство модулей не означает совпадения направлений.'),
        ('Докажи вывод для любого параллелограмма','При раскрытии (u+v)·(u−v) два смешанных слагаемых противоположны. Перпендикулярность вынуждает |u|²=|v|². Квадрат на втором чертеже тоже удовлетворяет этому доказательству.','Прямой угол только между соседними сторонами не гарантирует перпендикулярности диагоналей.'),
        ('Попробуй убрать гипотезу','В прямоугольнике 4 на 2 произведение AC·DB=4²−2²=12. Диагонали не перпендикулярны и соседние стороны не равны.','Вершины, у которых начинаются направляющие диагоналей, изменяют знак, но не условие равенства нулю.')],views,[
        ('Чему равно AC·DB у квадрата со стороной 3?','0','Квадраты длин соседних сторон равны.'),('Чему равно AC·DB у нового прямоугольника 4 на 2?','12','Вычти 2² из 4².')],[110,111,112],'T — точка пересечения диагоналей. Сравни два случая с равными сторонами и прямоугольник с разными сторонами.')
    return e


def similarity():
    def scene(title,x,y,inscribed):
        z=hypot(x,y);r=(x+y-z)/2 if inscribed else z/2
        center=(r,r) if inscribed else (x/2,y/2)
        pts={'A':(0,0),'B':(x,0),'C':(0,y),'T':center}
        if inscribed:pts['H']=(r,0)
        return drawing(title,pts,'AB BC CA TH' if inscribed else 'AB BC CA TA TB TC',('T',r))
    output=[]
    for inscribed in (False,True):
        views=[scene('Стороны 3, 4, 5',4,3,inscribed),scene('Сходственный треугольник со сторонами 6, 8, 10',8,6,inscribed),scene('Другая форма: равные катеты по 4',4,4,inscribed)]
        if inscribed:
            hint='Площадь треугольника равна произведению полупериметра p и радиуса вписанной окружности r. При подобии с коэффициентом k площади соотносятся как k², а полупериметры как k.'
            e=exercise(1166,'б','Докажи, что отношение радиусов вписанных окружностей двух подобных треугольников равно отношению их соответствующих сторон, взятых в том же порядке.',
                'Уточним порядок: если стороны второго равны сторонам первого, умноженным на k, то S₂=k²S₁ и p₂=kp₁. Из r=S/p следует r₂/r₁=(S₂/S₁)/(p₂/p₁)=k.',hint,[
                ('Свяжи радиус с площадью','Разбей треугольник от центра вписанной окружности на три. У каждой части высота к стороне равна r, поэтому S=r(a+b+c)/2=rp. У треугольника 3,4,5 площадь 6, p=6, r=1.','Полупериметр равен половине суммы трёх сторон.'),
                ('Сравни две формы одинаковых углов','Треугольник 6,8,10 вдвое больше по сторонам. Площадь 24 и полупериметр 12 дают r=2. Аналогично для всякого k>0 частное k²/k равно k.','Деление площадей само по себе дало бы k² вместо отношения радиусов.'),
                ('Вычисли для новой формы','У прямоугольного равнобедренного треугольника с катетами 4 гипотенуза 4√2. Его r=(4+4−4√2)/2=4−2√2. Он не подобен первым двум, поэтому отношение катетов к ним не задаёт отношение радиусов.','В выводе необходима именно подобность.')],views,[
                ('Каков радиус окружности внутри треугольника 6,8,10?','2','Раздели площадь 24 на полупериметр 12.'),('Каков коэффициент при √2 в выражении r=4−…√2 для новых катетов по 4?','2','Вычисли половину гипотенузы 4√2.')],[104,105],'T равноудалён от всех трёх сторон. TH — перпендикулярный радиус к AB, окружность касается всех сторон.')
        else:
            hint='У соответствующих сторон a₁,a₂ лежат напротив равные углы. По расширенной теореме синусов a=2R sin A. Подставь это для обоих треугольников.'
            e=exercise(1166,'а','Докажи, что отношение радиусов окружностей, описанных около двух подобных треугольников, равно отношению их соответствующих сторон.',
                'Если a₂/a₁=k, то против этих сторон в подобных треугольниках лежат равные углы A₁=A₂. Из R=a/(2 sin A) получаем R₂/R₁=a₂/a₁=k.',hint,[
                ('Выбери соответствующие элементы','Возьми сторону и угол напротив неё в каждом треугольнике. По теореме синусов их частное с удвоенным синусом равно R. В прямоугольном 3,4,5 половина гипотенузы даёт R=2,5.','Нельзя сравнивать произвольные разные стороны двух треугольников.'),
                ('Сократи равные синусы','В отношении радиусов множители 2 sin A одинаковы и положительны. Получается k. Для 6,8,10 радиус 5 и отношение 5/2,5=2.','В обоих отношениях второй треугольник должен находиться в числителе.'),
                ('Проверь другой вид треугольника','Теперь катеты равны 4, гипотенуза 4√2. В прямоугольном треугольнике центр описанной окружности лежит в середине гипотенузы, так что R=2√2 и R²=8.','Деление гипотенузы пополам относится к прямоугольному примеру; доказательство синусами действует для всех подобных треугольников.')],views,[
                ('Каков R у треугольника 6,8,10?','5','Возьми половину гипотенузы 10.'),('Каков R² у нового треугольника с катетами 4 и 4?','8','Половина квадрата гипотенузы не равна квадрату её половины: раздели 32 на 4.')],[105],'T — центр окружности, на которой лежат A, B, C. В этих прямоугольных примерах T — середина гипотенузы.')
        e['answer']['prompt']='Докажи равенство для любых двух подобных треугольников, сохранив порядок соответствующих величин.'
        output.append(e)
    return output


def build():
    entries=[trapezium(),circumradius(),rhombus_area(),weighted_point(),coordinate_trapezium(),*cevians(),rhombus_test(),*similarity()]
    return {'bookId':BOOK,'lessons':entries}


if __name__=='__main__':
    q=argparse.ArgumentParser()
    q.add_argument('--check',action='store_true')
    source=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if q.parse_args().check:assert OUT.read_text()==source
    else:OUT.write_text(source)
